package org.jlinalg.cli;

import htsjdk.samtools.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.zip.GZIPInputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;
import javax.imageio.ImageIO;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class DeepToolsMatrixCliTest {
    @TempDir Path directory;
    private String message;
    private Path file(String name,String content)throws Exception {Path path=directory.resolve(name);Files.writeString(path,content);return path;}
    private String home(){String value=System.getenv("JLINALG_DEEPTOOLS_HOME");Assumptions.assumeTrue(value!=null&&!value.isBlank(),"Original managed deepTools runtime not configured");return value;}
    private int run(String name,String method,String... extra)throws Exception {var args=new ArrayList<>(List.of("deep-tools","--method",method,"--out",directory.resolve(name).toString(),"--no-config"));args.addAll(List.of(extra));var bytes=new ByteArrayOutputStream();var stream=new PrintStream(bytes);int code=JLinAlgCli.run(args.toArray(String[]::new),stream,stream);message=bytes.toString();Path warnings=directory.resolve(name+"/WARNINGS.md");if(Files.exists(warnings))message+=Files.readString(warnings);return code;}
    private Path resource(String name)throws Exception {Path path=directory.resolve(name);try(var input=getClass().getResourceAsStream("/deeptools/"+name)){assertNotNull(input);Files.copy(input,path);}return path;}
    private String[] matrix(String runtime,Path samples,Path sizes,Path regions){return new String[]{"--runtime-home",runtime,"--samples",samples.toString(),"--sizes",sizes.toString(),"--genome-build","SYNTHETIC","--regions",regions.toString(),"--group-label","genes","--mode","reference-point","--reference-point","TSS","--bin-size","10","--upstream","20","--downstream","20","--missing","error","--skip-zero-rows","false","--bin-average","mean"};}
    private Path bam(String name,int[] starts)throws Exception {var header=new SAMFileHeader();header.setSortOrder(SAMFileHeader.SortOrder.coordinate);header.addSequence(new SAMSequenceRecord("chr1",1000));Path path=directory.resolve(name);try(var writer=new SAMFileWriterFactory().setCreateIndex(true).makeBAMWriter(header,true,path.toFile())){int index=0;for(int start:starts){var read=new SAMRecord(header);read.setReadName("read"+index++);read.setReferenceName("chr1");read.setAlignmentStart(start+1);read.setCigarString("10M");read.setMappingQuality(40);read.setReadString("AAAAAAAAAA");read.setBaseQualityString("IIIIIIIIII");writer.addAlignment(read);}}return path;}
    private Path manifest(String name,String[] labels,Path... inputs)throws Exception {var body=new StringBuilder("sample\tpath\n");for(int index=0;index<inputs.length;index++)body.append(labels[index]).append('\t').append(inputs[index].getFileName()).append('\n');return file(name,body.toString());}
    @Test void typedPoliciesRejectAmbiguousModesAndDependencySkipHasExplicitRecovery()throws Exception {
        assertEquals(2,run("wrong","matrix","--samples","missing","--sizes","missing","--genome-build","SYNTHETIC","--regions","missing","--group-label","genes","--mode","reference-point","--reference-point","TSS","--bin-size","10","--upstream","11","--downstream","20","--missing","error","--skip-zero-rows","false","--bin-average","mean"),message);assertTrue(message.contains("exact bin-size multiples"));assertFalse(Files.exists(directory.resolve("wrong")));
        assertEquals(3,run("skip","matrix",matrix(directory.resolve("absent-runtime").toString(),directory.resolve("missing-samples"),directory.resolve("missing-sizes"),directory.resolve("missing-regions"))),message);assertTrue(message.contains("If installation is forbidden"));assertTrue(message.contains("--environment NEW_RUNTIME_HOME"));assertFalse(Files.exists(directory.resolve("skip/model.json")));assertEquals("skipped-dependency",RegenieRuntime.object(directory.resolve("skip/analysis-status.json")).get("status"));
        assertEquals(2,run("dpi","correlation","--model","absent","--dpi","80","--correlation-method","pearson","--what-to-plot","heatmap","--zero-rows","keep"),message);assertTrue(message.contains("does not apply"));
    }
    @Test void actualStrandedMatrixProfileHeatmapAndChangedModelPreserveIdentities()throws Exception {
        String runtime=home();Path ramp=resource("ramp.bw"),control=resource("two.bw"),sizes=file("sizes","chr1\t1000\n"),regions=file("genes.bed","chr1\t200\t260\tplus\t0\t+\nchr1\t400\t460\tminus\t0\t-\n"),samples=manifest("tracks.tsv",new String[]{"1","control"},ramp,control);
        assertEquals(0,run("matrix","matrix",matrix(runtime,samples,sizes,regions)),message);
        List<String> lines;try(var stream=new GZIPInputStream(Files.newInputStream(directory.resolve("matrix/matrix.gz")))){lines=new String(stream.readAllBytes(),StandardCharsets.UTF_8).lines().toList();}assertEquals(3,lines.size());assertEquals(List.of("plus","minus"),lines.stream().skip(1).map(line->line.split("\t")[3]).toList());double[][] truth={{19,20,21,22,2,2,2,2},{48,47,46,45,2,2,2,2}};for(int row=0;row<2;row++){String[] fields=lines.get(row+1).split("\t");for(int column=0;column<8;column++)assertEquals(truth[row][column],Double.parseDouble(fields[column+6]),1e-12);}
        Path model=directory.resolve("matrix/model.json");String before=FollowupSupport.hash(model);assertEquals(0,run("profile","plot-profile","--runtime-home",runtime,"--model",model.toString(),"--average","mean"),message);String[] profile=Files.readAllLines(directory.resolve("profile/profile-data.tsv")).get(2).split("\t");assertEquals("1",profile[0]);assertEquals("genes",profile[1]);for(int index=2;index<profile.length;index++)assertEquals(33.5,Double.parseDouble(profile[index]));
        assertEquals(0,run("heatmap","plot-heatmap","--runtime-home",runtime,"--model",model.toString(),"--average","mean"),message);for(String plot:List.of("profile","heatmap")){var image=ImageIO.read(directory.resolve(plot+"/figure.png").toFile());assertNotNull(image);assertTrue(image.getWidth()>100&&image.getHeight()>100);assertTrue(Files.exists(directory.resolve(plot+"/region-status.tsv")));}assertEquals(before,FollowupSupport.hash(model));
        Files.write(directory.resolve("matrix/matrix.gz"),new byte[]{1},java.nio.file.StandardOpenOption.APPEND);assertEquals(2,run("tampered","plot-profile","--runtime-home",runtime,"--model",model.toString(),"--average","mean"),message);assertTrue(message.contains("Model member changed"));assertFalse(Files.exists(directory.resolve("tampered/figure.png")));assertFalse(Files.exists(directory.resolve("tampered/results.tsv")));
    }
    @Test void actualBamSummaryAndSpearmanHaveExactLabelsCountsAndIndependentReference()throws Exception {
        String runtime=home();Path a=bam("A.bam",new int[]{0,5,20}),b=bam("B.bam",new int[]{10,20,25}),samples=manifest("bams.tsv",new String[]{"A","B"},a,b),sizes=file("sizes","chr1\t1000\n");
        assertEquals(0,run("summary","bam-summary","--runtime-home",runtime,"--samples",samples.toString(),"--sizes",sizes.toString(),"--genome-build","SYNTHETIC","--mode","bins","--bin-size","10"),message);var rows=Files.readAllLines(directory.resolve("summary/results.tsv"));assertEquals(101,rows.size());assertEquals("chr1\t0\t10\t2.0\t0.0",rows.get(1));assertEquals("chr1\t20\t30\t1.0\t2.0",rows.get(3));
        assertEquals(0,run("correlation","correlation","--runtime-home",runtime,"--model",directory.resolve("summary/model.json").toString(),"--correlation-method","spearman","--what-to-plot","heatmap","--zero-rows","keep"),message);var coefficients=Files.readAllLines(directory.resolve("correlation/results.tsv"));assertEquals(5,coefficients.size());for(String row:coefficients.subList(1,coefficients.size())){String[] fields=row.split("\t");double actual=Double.parseDouble(fields[2]),truth=Double.parseDouble(fields[3]);assertEquals(truth,actual,5.1e-5);if(!fields[0].equals(fields[1]))assertEquals(.6528,actual,1e-4);}assertTrue(message.contains("No outlier removal"));
    }
    @Test void actualConstantSampleFailsWithNamedRecoveryAndNoFigure()throws Exception {
        String runtime=home();int[] everyBin=new int[100];for(int index=0;index<100;index++)everyBin[index]=index*10;Path a=bam("A.bam",new int[]{0,5,20}),constant=bam("constant.bam",everyBin),samples=manifest("bams.tsv",new String[]{"A","Const"},a,constant),sizes=file("sizes","chr1\t1000\n");assertEquals(0,run("summary","bam-summary","--runtime-home",runtime,"--samples",samples.toString(),"--sizes",sizes.toString(),"--genome-build","SYNTHETIC","--mode","bins","--bin-size","10"),message);
        assertEquals(2,run("constant","correlation","--runtime-home",runtime,"--model",directory.resolve("summary/model.json").toString(),"--correlation-method","pearson","--what-to-plot","heatmap","--zero-rows","keep"),message);assertTrue(message.contains("constant sample Const"));assertFalse(Files.exists(directory.resolve("constant/results.tsv")));assertFalse(Files.exists(directory.resolve("constant/figure.png")));assertTrue(Files.exists(directory.resolve("constant/partial/correlation-input-audit-execution.json")));
    }
    private static byte[] npy(String descriptor,String shape,byte[] data)throws Exception {String header="{'descr': '"+descriptor+"', 'fortran_order': False, 'shape': "+shape+", }\n";var output=new ByteArrayOutputStream();output.write(new byte[]{(byte)147,'N','U','M','P','Y',1,0,(byte)header.length(),(byte)(header.length()>>8)});output.write(header.getBytes(StandardCharsets.US_ASCII));output.write(data);return output.toByteArray();}
    @Test void actualObjectArrayHeaderIsRejectedBeforeAnyPickleLoading()throws Exception {
        String runtime=home();Path bundle=directory.resolve("fake-model");Files.createDirectory(bundle);Path npz=bundle.resolve("summary.npz");try(var archive=new ZipOutputStream(Files.newOutputStream(npz))){archive.putNextEntry(new ZipEntry("matrix.npy"));archive.write(npy("|O","(2,2)","NOT-A-PICKLE".getBytes(StandardCharsets.US_ASCII)));archive.closeEntry();archive.putNextEntry(new ZipEntry("labels.npy"));archive.write(npy("|S1","(2,)",new byte[]{'A','B'}));archive.closeEntry();}Files.writeString(bundle.resolve("reference.sizes"),"chr1\t1000\n");Files.writeString(bundle.resolve("samples.tsv"),"sample\tpath\nA\ta\nB\tb\n");Files.writeString(bundle.resolve("results.tsv"),"unused\n");var hashes=new LinkedHashMap<String,String>();for(String name:List.of("summary.npz","reference.sizes","samples.tsv","results.tsv"))hashes.put(name,FollowupSupport.hash(bundle.resolve(name)));Files.writeString(bundle.resolve("model.json"),RegenieRuntime.json(Map.of("schema","jlinalg-deeptools-summary-v1","upstream_version","3.5.6","genome_build","SYNTHETIC","labels",List.of("A","B"),"files",hashes)));
        assertEquals(2,run("object","correlation","--runtime-home",runtime,"--model",bundle.resolve("model.json").toString(),"--correlation-method","pearson","--what-to-plot","heatmap","--zero-rows","keep"),message);assertTrue(message.contains("Object/pickled or unsupported summary arrays are forbidden"));assertFalse(Files.exists(directory.resolve("object/figure.png")));assertFalse(Files.exists(directory.resolve("object/results.tsv")));
    }
}
